{
  "skill": "clarify",
  "note": "Measures DESCRIPTION SEPARABILITY, not routing. See evals/routing/README.md.",
  "top_k": 5,
  "positive": [
    "this request is ambiguous and could be interpreted multiple ways",
    "ask me a reverse question before you start",
