  "negative": [
    {
      "prompt": "create an implementation plan with bite-sized tasks and an operations config",
      "owner": "writing-plans"
    },
    {
      "prompt": "show executed evidence before claiming the work is complete",
      "owner": "verification-before-completion"
    }
  ],
  "expectation": "Returns questions under the reverse-question protocol instead of guessing an interpretation and proceeding."
}

{
  "skill": "writing-plans",
  "note": "Measures DESCRIPTION SEPARABILITY, not routing. See evals/routing/README.md.",
  "top_k": 5,
  "positive": [
    "create an implementation plan for this change",
    "break this into bite-sized tasks with an operations config",
