    "work through why this defect happens, methodically"
  ],
  "negative": [
    {
      "prompt": "write the implementation plan with bite-sized tasks",
      "owner": "writing-plans"
    },
    {
      "prompt": "the ask is ambiguous, question me before starting",
      "owner": "clarify"
    }
  ],
  "expectation": "Runs the four-phase investigation and names a root cause with evidence, rather than proposing a symptomatic fix."
