{
  "skill": "verification-before-completion",
  "note": "Measures DESCRIPTION SEPARABILITY, not routing. See evals/routing/README.md.",
  "top_k": 5,
  "positive": [
    "I am about to claim this work is complete",
    "run the pre-PR quality gate before saying it passes",
    "what executed evidence is required before a success claim"
  ],
  "negative": [
    {
      "prompt": "the request is ambiguous, could be interpreted multiple ways",
      "owner": "clarify"
    },
    {
      "prompt": "diagnose the root cause of this crash",
      "owner": "systematic-debugging"
    }
  ],
  "expectation": "Refuses the completion claim until the build, types, lint, tests, security and diff runbook has produced executed output."
